fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    // If the input slice is empty, return an empty Vec.
    if n == 0 {
        return Vec::new();
    }

    // We know the result will have exactly 2*n - 1 elements.
    let mut result = Vec::with_capacity(2 * n - 1);

    // Push the first element, then for each subsequent element
    // push the delimiter followed by the element.
    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            result.push(delim);
        }
        result.push(num);
    }

    result
}

